func latestNonReviewAgent(ctx context.Context, reader checkpoint.CommittedReader, cpID id.CheckpointID, summary *checkpoint.CheckpointSummary) string {
	for i := len(summary.Sessions) - 1; i >= 0; i-- {
		content, err := reader.ReadSessionContent(ctx, cpID, i)
		if err != nil {
			logging.Debug(ctx, "review brief: read checkpoint session",
				slog.String("checkpoint_id", cpID.String()),
				slog.Int("session_index", i),
				slog.String("error", err.Error()))
			continue
		}
		if session.Kind(content.Metadata.Kind).IsReview() {
			continue
		}
		if content.Metadata.Agent != "" {
			ag, err := agent.GetByAgentType(content.Metadata.Agent)
			if err == nil {
				return string(ag.Name())
			}
			return string(content.Metadata.Agent)
		}
	}
	return ""
}
